    goal_node = graph.nodes[goal]
    if start_node is goal_node:
        return [start]
    visited = set()
    to_visit = [(start_node, [start])]
    while to_visit:
        current_node, path = to_visit.pop(0)
        visited.add(current_node)
        for neighbor in current_node.neighbors:
            if neighbor not in visited:
                if neighbor is goal_node:
                    return path + [neighbor.id]
                else:
                    to_visit.append((neighbor, path + [neighbor.id]))
    return None
