def find_path(graph, start, goal):
    """
    Finds a path from start to goal in the graph using a path search algorithm.
    """
    if start == goal:
        return [start)

    # Keep track of visited nodes to avoid cycles
    visited = set()
    # Store the path from start to the current node
    path = []

    def search(node):
        if node in visited:
            return False
        visited.add(node)
        if node == goal:
            return True
        path.append(node)
        for neighbor in graph.get(node, []):
            if search(neighbor):
                return True
        path.pop()
        return False

    search(start)
    return path if path else None

class Graph:

    def __init__(self, directed=True):
        self.directed = directed
        self.graph = {}

    def add_node(self, node):
        if not self.graph.__contains__(node):
            self.graph[node] = []

    def add_edge(self, start, goal):
        if start in self.graph:
            self.graph[start].append(goal)
        if not self.directed:
            if goal in self.graph:
                self.graph[goal].append(start)

    def find_path(self, start, goal):
        if not self.graph.__contains__(start) or not self.graph.__contains__(goal):
            return None
        visited = set()
        path = []

        def explore(current, goal):
            if current == goal:
                return True
            visited.add(current)
            path.append(current)
            if goal in self.graph[current]:
                return True
            neighbours = self.graph[current]
            for neighbour in neighbours:
                if neighbour not in visited:
                    if explore(neighbour, goal):
                        return True
            path.pop()
            return False
        if explore(start, goal):
            return path
        else:
            return None
