class GraphSearch:

    def find_path(self, graph, start, goal):
        path = []
        seen = set()
        path.append(start)
        while path:
            current_node = path.pop()
            if current_node not in seen:
                seen.add(current_node)
                if current_node == goal:
                    return path
                neighbors = graph.get(current_node, [])
                path.extend((n for n in neighbors if n not in seen))
        return None
